 const reverse=new Map();for(const [es,values] of Object.entries(rows)){reverse.set(es,es);for(const value of values)if(!reverse.has(value))reverse.set(value,es);}
 let language='es',source='default';
 const textOriginal=new WeakMap(),attributeOriginal=new WeakMap();
 const sourceText=value=>rows[value]?value:(reverse.get(value)||value);
 // Only these interface messages accept numeric substitutions. Usernames,
 // captions and other user content never become translation templates.
 const numericRows=[
  [/^Entre (\d+(?:,\d{1,2})?) y (\d+(?:,\d{1,2})?) €$/,'Entre {min} y {max} €',['min','max']],
  [/^Elige una cantidad entre (\d+(?:,\d{1,2})?) y (\d+(?:,\d{1,2})?) €\.$/,'Elige una cantidad entre {min} y {max} €.',['min','max']],
  [/^Preparando una aportación única de (\d+(?:,\d{1,2})?) €…$/,'Preparando una aportación única de {amount} €…',['amount']],
  [/^Página (\d+) de (\d+)$/,'Página {page} de {pages}',['page','pages']],
  [/^(\d+) vídeos publicados\.$/,'{count} vídeos publicados.',['count']],
  [/^(\d+) vídeos en tu cuenta\.$/,'{count} vídeos en tu cuenta.',['count']],
  [/^(\d+) vídeos en este estado\.$/,'{count} vídeos en este estado.',['count']],
  [/^(\d+) avisos recibidos$/,'{count} avisos recibidos',['count']],
  [/^(\d+) cuentas · selecciona una para ver su ficha\.$/,'{count} cuentas · selecciona una para ver su ficha.',['count']],
  [/^(\d+) de (\d+) insignias de fundador asignadas$/,'{claimed} de {limit} insignias de fundador asignadas',['claimed','limit']],
  [/^Tu insignia de fundador n\.º (\d+)$/,'Tu insignia de fundador n.º {number}',['number']],
  [/^Tu insignia de fundador n\.º (\d+)\. Tu número es personal, exclusivo y permanente\. Emitir requiere acceso vigente a Ol Live\.( No tienes obligación de emitir\.)?$/,'Tu insignia de fundador n.º {number}. Tu número es personal, exclusivo y permanente. Emitir requiere acceso vigente a Ol Live.',['number']],
  [/^Tu número de fundador n\.º (\d+) está desactivado\. Contacta con administración\.$/,'Tu número de fundador n.º {number} está desactivado. Contacta con administración.',['number']]
 ];
 const t=(text,lang=language)=>{
  const original=sourceText(String(text)),index=LANGS.indexOf(lang)-1;
  if(lang==='es'||index<0)return original;
  if(rows[original])return rows[original][index]||original;
  for(const [pattern,key,fields] of numericRows){const match=original.match(pattern);if(!match)continue;let translated=rows[key][index];fields.forEach((field,i)=>{translated=translated.replaceAll('{'+field+'}',match[i+1]);});if(match[fields.length+1])translated+=' '+rows['No tienes obligación de emitir.'][index];return translated;}
  return original;
 };
 const protectedSelector='script,style,code,pre,textarea,[contenteditable],[data-user-content],.site-language,.track-title,.track-artist,#player-title,#player-artist,#member-title,datalist,.rail-channel>span,.founder-personal-emblem,.live-channel h3,.live-channel p,#live-comments,#stage-title,#studio-title,#admin-members,#admin-moderation,#admin-payments,#guest-journey-list,#guest-journey-events,#visitor-registry-list,#recordings-list,blockquote[lang],[data-original-language],[translate="no"]';
 function protectedNode(element){return !element||Boolean(element.closest(protectedSelector));}
 function translateText(node){const parent=node.parentElement;if(protectedNode(parent))return;const raw=node.nodeValue,trimmed=raw.trim();if(!trimmed)return;let original=textOriginal.get(node);if(!original||raw!==t(original)&&raw!==original)original=raw;textOriginal.set(node,original);const core=original.trim(),translated=t(core);const result=original.replace(core,translated);if(node.nodeValue!==result)node.nodeValue=result;}
 function attributes(element){if(protectedNode(element))return;let originals=attributeOriginal.get(element);if(!originals){originals={};attributeOriginal.set(element,originals);}for(const name of ['placeholder','title','aria-label']){const value=element.getAttribute(name);if(!value)continue;if(!originals[name]||value!==t(originals[name])&&value!==originals[name])originals[name]=value;const translated=t(originals[name]);if(value!==translated)element.setAttribute(name,translated);}}
 function translate(root){if(root.nodeType===Node.TEXT_NODE){translateText(root);return;}if(root.nodeType!==Node.ELEMENT_NODE||protectedNode(root))return;attributes(root);const walker=document.createTreeWalker(root,NodeFilter.SHOW_ELEMENT|NodeFilter.SHOW_TEXT,{acceptNode:node=>node.nodeType===Node.ELEMENT_NODE&&protectedNode(node)?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});let current;while((current=walker.nextNode())){if(current.nodeType===Node.TEXT_NODE)translateText(current);else attributes(current);}}
 let frame=null;const pending=new Set();function queue(root){if(!root)return;pending.add(root);if(frame)return;frame=requestAnimationFrame(()=>{frame=null;const work=[...pending];pending.clear();for(const item of work)if(item.isConnected)translate(item);});}
 function update(next,reason){if(!LANGS.includes(next))next='es';language=next;source=reason;document.documentElement.lang=language;for(const control of document.querySelectorAll('[data-site-language]'))control.value=reason==='saved'?language:'auto';for(const label of document.querySelectorAll('[data-site-language-label]'))label.textContent=t('Idioma');translate(document.body);window.dispatchEvent(new CustomEvent('electronicama:language-change',{detail:{language,source}}));window.dispatchEvent(new CustomEvent('ol:language-changed',{detail:{language,source}}));}
 function saved(){try{const value=localStorage.getItem(KEY);return LANGS.includes(value)?value:null;}catch{return null;}}
 function browser(){return (navigator.languages||[navigator.language]).map(tag=>tag.toLowerCase().split('-')[0]).find(tag=>LANGS.includes(tag))||'es';}
 let automaticRevision=0;
 async function automatic(){const revision=++automaticRevision;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),4000);try{const response=await fetch('/api/locale',{cache:'no-store',signal:controller.signal});if(!response.ok)throw Error();const data=await response.json();if(revision===automaticRevision&&!saved())update(data.language,data.source||'automatic');}catch{if(revision===automaticRevision&&!saved())update(browser(),'browser');}finally{clearTimeout(timeout);}}
 const legal=location.pathname.startsWith('/legal/');if(legal){const main=document.querySelector('main');if(main){main.dataset.originalLanguage='es';main.lang='es';}}
 const panel=document.createElement('label');panel.className='site-language';panel.setAttribute('aria-label','Idioma / Language');const label=document.createElement('span');label.dataset.siteLanguageLabel='';label.textContent='Idioma';const select=document.createElement('select');select.dataset.siteLanguage='';select.setAttribute('aria-label','Idioma / Language');for(const [value,name] of [['auto','Automático'],['es','Español'],['ca','Català'],['en','English'],['fr','Français'],['pt','Português'],['de','Deutsch'],['it','Italiano']])select.add(new Option(name,value));panel.append(label,select);(document.querySelector('.topbar,.platform-header')||document.querySelector('footer')||document.body).append(panel);
 select.addEventListener('change',()=>{const value=select.value;try{if(value==='auto')localStorage.removeItem(KEY);else localStorage.setItem(KEY,value);}catch{}if(value==='auto'){document.cookie=KEY+'=; Max-Age=0; Path=/; SameSite=Lax';automatic();}else{document.cookie=KEY+'='+value+'; Max-Age=31536000; Path=/; SameSite=Lax'+(location.protocol==='https:'?'; Secure':'');update(value,'saved');}});
 new MutationObserver(records=>{for(const record of records)queue(record.type==='characterData'?record.target:record.target);}).observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','title','aria-label']});
 window.addEventListener('storage',event=>{if(event.key!==KEY)return;const choice=saved();if(choice)update(choice,'saved');else automatic();});
 window.OlLocale={t,get language(){return language;},get source(){return source;},refresh:()=>update(language,source)};
 const choice=saved();if(choice)update(choice,'saved');else automatic();
